        public bool ModbusWriteAll()
        {
            bool _status = true;
        
            _status &= MainForm.modbusExt.ModbusWrite(7, 0, serialNo, typeof(UInt32), 1);
            _status &= MainForm.modbusExt.ModbusWrite(9, 0, hwVersionMajor, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(10, 0, hwVersionMinor, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(11, 0, productionYear, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(12, 0, productionMonth, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(13, 0, productionDay, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(200, 0, memoryRetryQty, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(201, 0, memoryRetryDelayMs, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(400, 0, watchdogTimeMs, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(409, 0, dateYearConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(410, 0, dateMonthConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(411, 0, dateDayConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(412, 0, clockHourConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(413, 0, clockMinuteConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(414, 0, clockSecondConfig, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(900, 0, upStreamBaudrate, typeof(UInt32), 1);
            _status &= MainForm.modbusExt.ModbusWrite(2000, 0, shodowHoldingRegisterConfig, typeof(UInt16), 1000);
            _status &= MainForm.modbusExt.ModbusWrite(4000, 0, slaveId, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4001, 0, identifyStatus, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4004, 0, downStreamBaudrate, typeof(UInt32), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4034, 0, upStreamDelayBetweenFrameUs, typeof(UInt16), 1);

            for (int i = 0; i < 2; i++)
            {
                downStreamsSetting[i].ModbusWriteAll();
            }

            _status &= MainForm.modbusExt.ModbusWrite(4089, 0, streamerEnable, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4090, 0, streamerExtendedHeaderEnable, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4091, 0, streamerInternalClockIntervalMs, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4092, 0, streamerPrescaler, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4093, 0, streamerParameterIds, typeof(UInt16), 200);
            _status &= MainForm.modbusExt.ModbusWrite(4301, 0, boardStartupDelayMs, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4302, 0, boardStartupRetryQty, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4303, 0, boardStartupRetryDelayMs, typeof(UInt16), 1);

            for (int i = 0; i < 3; i++)
            {
                ad7177_Setting[i].ModbusWriteAll();
            }

            for (int i = 0; i < 3; i++)
            {
                snj_Setting[i].ModbusWriteAll();
            }

            for (int i = 0; i < 3; i++)
            {
                fog_Setting[i].ModbusWriteAll();
            }

            _status &= xrza_Setting.ModbusWriteAll();
            _status &= internalImu_Setting.ModbusWriteAll();
            _status &= MainForm.modbusExt.ModbusWrite(4732, 0, fogHeaterPwmFreqHz, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(4733, 0, outDataUartToMcuAlgBaudRate, typeof(UInt32), 1);
            _status &= mainLoopProfilerSetting.ModbusWriteAll();
            _status &= MainForm.modbusExt.ModbusWrite(4760, 0, calcFreqHz, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(5363, 0, debugControlSignalsF64, typeof(Double), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5563, 0, debugControlSignalsF32, typeof(Single), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5663, 0, debugControlSignalsU32, typeof(UInt32), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5763, 0, debugControlSignalsI32, typeof(Int32), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5863, 0, debugControlSignalsU16, typeof(UInt16), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5913, 0, debugControlSignalsI16, typeof(Int16), 50);
            _status &= MainForm.modbusExt.ModbusWrite(5965, 0, outputUpdatePrescaler, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(5966, 0, sensorGyroEnable, typeof(UInt16), 20);
            _status &= MainForm.modbusExt.ModbusWrite(6946, 0, sensorGyroI32_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(6950, 0, sensorGyroTemperatureI16_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(6954, 0, sensorGyroTemperatureRateI16_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(6958, 0, sensorAccEnable, typeof(UInt16), 20);
            _status &= MainForm.modbusExt.ModbusWrite(7938, 0, sensorAccI32_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(7942, 0, sensorAccTemperatureI16_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(7946, 0, sensorAccTemperatureRateI16_Range, typeof(Double), 1);
            _status &= MainForm.modbusExt.ModbusWrite(7950, 0, sensorCalibCoefBankQty, typeof(UInt32), 1);
            _status &= MainForm.modbusExt.ModbusWrite(7952, 0, sensorCalibCoefBank, typeof(Double), 4000);
            _status &= MainForm.modbusExt.ModbusWrite(23952, 0, rotationAnglesCoordinateDegree, typeof(Double), 3);
            _status &= MainForm.modbusExt.ModbusWrite(23964, 0, rotationAnglesTuneDegree, typeof(Double), 3);
            _status &= MainForm.modbusExt.ModbusWrite(23976, 0, rotationAnglesTemporaryDegree, typeof(Double), 3);
            _status &= filterSetting.ModbusWriteAll();
            _status &= MainForm.modbusExt.ModbusWrite(24130, 0, chipStabilizationCycleQty, typeof(UInt16), 1);
            _status &= MainForm.modbusExt.ModbusWrite(24131, 0, outputStabilizationCycleQty, typeof(UInt16), 1);
            
            if (!_status)
            {
                MessageBox.Show("Writing all parameters failed!", "Modbus error ...", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
            return _status;
        }

