                    fog_Setting[i].ModbusReadAll();
                }

                xrza_Setting.ModbusReadAll();
                internalImu_Setting.ModbusReadAll();
                fogHeaterPwmFreqHz = MainForm.modbusExt.ModbusRead(4732, 0, typeof(UInt16), 1);
