                sensorAccTemperatureRateI16_Range = MainForm.modbusExt.ModbusRead(7946, 0, typeof(Double), 1);
                sensorCalibCoefBankQty = MainForm.modbusExt.ModbusRead(7950, 0, typeof(UInt32), 1);
                sensorCalibCoefBank = MainForm.modbusExt.ModbusRead(7952, 0, typeof(Double), 4000);
                rotationAnglesCoordinateDegree = MainForm.modbusExt.ModbusRead(23952, 0, typeof(Double), 3);
                rotationAnglesTuneDegree = MainForm.modbusExt.ModbusRead(23964, 0, typeof(Double), 3);
                rotationAnglesTemporaryDegree = MainForm.modbusExt.ModbusRead(23976, 0, typeof(Double), 3);
                filterSetting.ModbusReadAll();
                chipStabilizationCycleQty = MainForm.modbusExt.ModbusRead(24130, 0, typeof(UInt16), 1);
                outputStabilizationCycleQty = MainForm.modbusExt.ModbusRead(24131, 0, typeof(UInt16), 1);
            
                readedOnce = true;
