        [TypeConverter(typeof(ExpandableObjectConverter))]
        public class sInternalImuData
        {
            public s3d acc;
            public Single[] accTemperature;
            public UInt16 version;
            public UInt16 counter;
            public UInt32 responseCountErrorCounter;
            public UInt16 responseCountErrorStatus;
            public UInt32 deserializedErrorCounter;
            public UInt16 deserializedErrorStatus;
            public UInt32 noResponseErrorCounter;
            public UInt16 noResponseErrorStatus;
            public UInt16 serialNo;
            public UInt32 status;
            public UInt16 active;

            private UInt16 ModbusBaseAddr;

            public static UInt16 ModbusSize = 33; // VarTypeSize in excel
            
            public sInternalImuData(UInt16 ObjectModbusBaseAddr)
            {
                ModbusBaseAddr = ObjectModbusBaseAddr;

                acc = new s3d((UInt16)(ModbusBaseAddr + 0));
                accTemperature = new Single[3];
                version = 0;
                counter = 0;
                responseCountErrorCounter = 0;
                responseCountErrorStatus = 0;
                deserializedErrorCounter = 0;
                deserializedErrorStatus = 0;
                noResponseErrorCounter = 0;
                noResponseErrorStatus = 0;
                serialNo = 0;
                status = 0;
                active = 0;
            }

            public s3d Acc
            {
                get { return acc; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 0, value, typeof(s3d), 1))
                    {
                        acc = value;
                    }
                }
            }

            public Single[] AccTemperature
            {
                get { return accTemperature; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 12, value, typeof(Single), 3))
                    {
                        accTemperature = value;
                    }
                }
            }

            public UInt16 Version
            {
                get { return version; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 18, value, typeof(UInt16), 1))
                    {
                        version = value;
                    }
                }
            }

            public UInt16 Counter
            {
                get { return counter; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 19, value, typeof(UInt16), 1))
                    {
                        counter = value;
                    }
                }
            }

            public UInt32 ResponseCountErrorCounter
            {
                get { return responseCountErrorCounter; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 20, value, typeof(UInt32), 1))
                    {
                        responseCountErrorCounter = value;
                    }
                }
            }

            public UInt16 ResponseCountErrorStatus
            {
                get { return responseCountErrorStatus; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 22, value, typeof(UInt16), 1))
                    {
                        responseCountErrorStatus = value;
                    }
                }
            }

            public UInt32 DeserializedErrorCounter
            {
                get { return deserializedErrorCounter; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 23, value, typeof(UInt32), 1))
                    {
                        deserializedErrorCounter = value;
                    }
                }
            }

            public UInt16 DeserializedErrorStatus
            {
                get { return deserializedErrorStatus; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 25, value, typeof(UInt16), 1))
                    {
                        deserializedErrorStatus = value;
                    }
                }
            }

            public UInt32 NoResponseErrorCounter
            {
                get { return noResponseErrorCounter; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 26, value, typeof(UInt32), 1))
                    {
                        noResponseErrorCounter = value;
                    }
                }
            }

            public UInt16 NoResponseErrorStatus
            {
                get { return noResponseErrorStatus; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 28, value, typeof(UInt16), 1))
                    {
                        noResponseErrorStatus = value;
                    }
                }
            }

            public UInt16 SerialNo
            {
                get { return serialNo; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 29, value, typeof(UInt16), 1))
                    {
                        serialNo = value;
                    }
                }
            }

            public UInt32 Status
            {
                get { return status; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 30, value, typeof(UInt32), 1))
                    {
                        status = value;
                    }
                }
            }

            public UInt16 Active
            {
                get { return active; }
                set
                {
                    if(MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 32, value, typeof(UInt16), 1))
                    {
                        active = value;
                    }
                }
            }

            public bool ModbusWriteAll()
            {
                bool _status = true;
            
                _status &= acc.ModbusWriteAll();
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 12, accTemperature, typeof(Single), 3);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 18, version, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 19, counter, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 20, responseCountErrorCounter, typeof(UInt32), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 22, responseCountErrorStatus, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 23, deserializedErrorCounter, typeof(UInt32), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 25, deserializedErrorStatus, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 26, noResponseErrorCounter, typeof(UInt32), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 28, noResponseErrorStatus, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 29, serialNo, typeof(UInt16), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 30, status, typeof(UInt32), 1);
                _status &=  MainForm.modbusExt.ModbusWrite(ModbusBaseAddr, 32, active, typeof(UInt16), 1);
                
                if (!_status)
                {
                    MessageBox.Show("Writing all parameters failed!", "Modbus error ...", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
                return _status;
            }

            public void ModbusReadAll()
            {
                acc.ModbusReadAll();
                accTemperature = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 12, typeof(Single), 3);
                version = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 18, typeof(UInt16), 1);
                counter = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 19, typeof(UInt16), 1);
                responseCountErrorCounter = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 20, typeof(UInt32), 1);
                responseCountErrorStatus = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 22, typeof(UInt16), 1);
                deserializedErrorCounter = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 23, typeof(UInt32), 1);
                deserializedErrorStatus = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 25, typeof(UInt16), 1);
                noResponseErrorCounter = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 26, typeof(UInt32), 1);
                noResponseErrorStatus = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 28, typeof(UInt16), 1);
                serialNo = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 29, typeof(UInt16), 1);
                status = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 30, typeof(UInt32), 1);
                active = MainForm.modbusExt.ModbusRead(ModbusBaseAddr, 32, typeof(UInt16), 1);
            }
        }

